                "تخريج الحديث" to "رواه البخاري (6227) ومسلم (2841) من حديث أبي هريرة في قصة خلق آدم وتسليمه على الملائكة، ورواه مسلم (2612) في النهي عن ضرب الوجه.",
                "أقوال العلماء في معناه" to "1. أن الضمير يعود على آدم: أي خلقه الله على صورته التي كان عليها، تاما مكتملا من أول خلقه، طوله ستون ذراعا، لم يتنقل في أطوار كذريته. وهو قول جماعة من العلماء.\n2. أن الضمير يعود على المضروب: أي على صورة هذا الوجه الذي تضربه، فاحترم صورة أبيك آدم، وهذا في رواية النهي عن ضرب الوجه.\n3. أن الضمير يعود على الله تعالى: وهو قول الإمام أحمد وإسحاق بن راهويه، وقرره ابن تيمية وابن عثيمين. والمعنى عندهم: أن الله خلق آدم على صورة اختارها له وأضافها إلى نفسه إضافة تشريف وتكريم، كما قال «ناقة الله» و«بيت الله»؛ أو أن لله صورة تليق به، وليس في ذلك مماثلة، كما أن لله وجها وسمعا وبصرا ولا يماثل وجه المخلوق ولا سمعه ولا بصره.",
                "لا يلزم من «على صورته» المماثلة" to "قال ابن عثيمين ما معناه: لا يلزم من كونه على صورته أن يكون مماثلا له، والدليل قوله ﷺ: «إن أول زمرة يدخلون الجنة على صورة القمر ليلة البدر» (متفق عليه)، وليسوا مثل القمر في كل شيء، وإنما في الحسن والإضاءة. فالمشاركة في أصل المعنى لا تقتضي التماثل في الحقيقة والكيفية.",
                "موقف المسلم من هذا الحديث" to "• الإيمان بالحديث كما جاء، فهو صحيح متفق عليه.\n• اعتقاد أن الله لا يماثله شيء من خلقه: ﴿ليس كمثله شيء وهو السميع البصير﴾.\n• عدم الخوض في الكيفية، والتسليم كما سلم السلف.",
                "من فوائد الحديث" to "• تكريم الله لآدم وذريته: ﴿ولقد كرمنا بني آدم﴾ [الإسراء: 70].\n• النهي عن ضرب الوجه ولو في القتال أو التأديب، وعن تقبيحه وسبه، ومنه قول: «قبح الله وجهك».\n• أن آدم خلق تاما طوله ستون ذراعا، وأن الخلق ما زال ينقص بعده.\n• مشروعية السلام، فهو تحية آدم وذريته.",
            ),
            sources = listOf(
                "صحيح البخاري (6227)، صحيح مسلم (2841، 2612)",
                "ابن تيمية، بيان تلبيس الجهمية، مبحث حديث الصورة",
                "ابن عثيمين، شرح العقيدة الواسطية",
                "النووي، المنهاج شرح صحيح مسلم",
            ),
        ),

        Extra("salim", "رضاع الكبير: «أرضعيه تحرمي عليه»", listOf("58175"),
            hadith = "عن عائشة رضي الله عنها قالت: جاءت سهلة بنت سهيل إلى النبي ﷺ فقالت: يا رسول الله، إني أرى في وجه أبي حذيفة من دخول سالم وهو حليفه، فقال النبي ﷺ: «أرضعيه» قالت: وكيف أرضعه وهو رجل كبير؟ فتبسم رسول الله ﷺ وقال: «قد علمت أنه رجل كبير». وفي رواية: «أرضعيه تحرمي عليه، ويذهب الذي في نفس أبي حذيفة». رواه مسلم (1453).",
            note = "هذه واقعة خاصة بسالم لحال لا تتكرر اليوم: كان ابنا بالتبني تربى في بيت أبي حذيفة، ثم أبطل الله التبني. وجمهور العلماء ومنهم سائر أمهات المؤمنين على أن رضاع الكبير لا يحرم، وأن الرضاع المحرم ما كان في الصغر. والإرضاع لم يكن بالتقام الثدي على ما ذكره أهل العلم، بل يحلب له اللبن فيشربه.",
            sections = listOf(
                "تخريج الحديث" to "رواه مسلم في صحيحه (1453) من طرق عن عائشة رضي الله عنها، وفي الباب نفسه (1454) قول أم سلمة: «أبى سائر أزواج النبي ﷺ أن يدخلن عليهن أحدا بتلك الرضاعة، وقلن لعائشة: والله ما نرى هذا إلا رخصة أرخصها رسول الله ﷺ لسالم خاصة».",
                "سبب القصة" to "كان أبو حذيفة قد تبنى سالما في الجاهلية على عادة العرب، فنشأ في بيته كالابن يدخل على زوجته سهلة. فلما أنزل الله ﴿ادعوهم لآبائهم هو أقسط عند الله﴾ [الأحزاب: 5] وأبطل التبني، صار سالم أجنبيا عنها، وهو يعيش معهم في بيت واحد، فشق ذلك عليهم، ووجد أبو حذيفة في نفسه. فجعل النبي ﷺ لهم هذا المخرج.",
                "كيف كان الإرضاع؟" to "نقل النووي عن القاضي عياض قوله: لعلها حلبته ثم شربه، من غير أن يمس ثديها ولا التقت بشرتاهما. وهذا هو اللائق، فالنبي ﷺ لا يأمر بما فيه كشف عورة لأجنبي. وقد ذكر ابن سعد في الطبقات أنها كانت تحلب في مسعط أو إناء قدر رضعة فيشربه سالم.",
                "أقوال العلماء في رضاع الكبير" to "1. جمهور العلماء من الصحابة والتابعين والأئمة الأربعة: رضاع الكبير لا يحرم، والحديث خاص بسالم. ودليلهم: قوله تعالى ﴿والوالدات يرضعن أولادهن حولين كاملين لمن أراد أن يتم الرضاعة﴾ [البقرة: 233]، وقوله ﷺ: «إنما الرضاعة من المجاعة» (متفق عليه)، وقول سائر أمهات المؤمنين.\n2. عائشة رضي الله عنها: يحرم رضاع الكبير مطلقا، وبه قال الليث بن سعد وابن حزم.\n3. ابن تيمية وابن القيم: الأصل أن الرضاع المحرم في الصغر، ويستثنى من كانت حاله كحال سالم، تدعو الحاجة إلى دخوله ويشق الاحتجاب منه.\nوقرر ابن عثيمين ما معناه: أن حال سالم إنما نشأت من التبني، وقد أبطل التبني فلا تتكرر هذه الحال اليوم، فلا يعمل بإرضاع الكبير.",
                "دفع الشبهات" to "• من استدل بالحديث على إرضاع الرجال الأجانب في العمل أو غيره فقد خالف الحديث نفسه وأقوال أهل العلم كلها، فلا يقول به عالم معتبر، وهي فتوى شاذة ردها العلماء.\n• ليس في الحديث ما ينكر، فقد أمر النبي ﷺ بحل شرعي لأسرة وقعت في حرج بعد تشريع جديد، مع حفظ العورات.\n• تبسم النبي ﷺ وقوله «قد علمت أنه رجل كبير» يدل على أنه أراد حكما خاصا لحالة خاصة.",
                "من فوائد الحديث" to "• رحمة الشريعة ورفع الحرج عن الناس عند تغير الأحكام.\n• غيرة الرجل على أهله محمودة، وأن الشريعة تراعيها.\n• أن الرضاع المحرم في الأصل ما كان في الصغر.\n• أدب أمهات المؤمنين واجتهادهن، ورد المسائل إلى الدليل.",
            ),
            sources = listOf(
                "صحيح مسلم، كتاب الرضاع، باب رضاعة الكبير (1453، 1454)",
                "النووي، المنهاج شرح صحيح مسلم (نقله عن القاضي عياض)",
                "ابن القيم، زاد المعاد، فصل رضاع الكبير",
                "ابن عثيمين، الشرح الممتع، كتاب الرضاع",
                "ابن سعد، الطبقات الكبرى، ترجمة سهلة بنت سهيل",
            ),
        ),

        Extra("sihr", "سحر النبي ﷺ", listOf("10570", "66092"),
            hadith = "عن عائشة رضي الله عنها قالت: سحر رسول الله ﷺ رجل من بني زريق يقال له لبيد بن الأعصم، حتى كان رسول الله ﷺ يخيل إليه أنه كان يفعل الشيء وما فعله... الحديث، وفيه أن ملكين أخبراه بالسحر وموضعه في بئر ذروان، فاستخرجه وشفاه الله. متفق عليه: البخاري (5763) ومسلم (2189).",
            note = "السحر أصاب النبي ﷺ في بدنه كما يصيب المرض، ولم يؤثر في عقله ولا في الوحي ولا في تبليغ الرسالة، فهو معصوم في ذلك بإجماع المسلمين. وكان أثره في أمور دنيوية كما في رواية البخاري: «حتى كان يرى أنه يأتي النساء ولا يأتيهن».",
            sections = listOf(
                "تخريج الحديث" to "متفق عليه من حديث عائشة رضي الله عنها: البخاري (5763، 5765، 3268) ومسلم (2189). وتلقته الأمة بالقبول، ولم يطعن فيه أحد من أئمة الحديث.",
                "القصة باختصار" to "سحره لبيد بن الأعصم اليهودي في مشط ومشاطة (ما يسقط من الشعر) وجف طلع نخلة ذكر (غلافه)، ودفنه في بئر ذروان. فلبث النبي ﷺ مدة يخيل إليه أنه فعل الشيء ولم يفعله، ثم دعا الله فأتاه ملكان فأخبراه بالسحر ومكانه، فأخرجه وشفاه الله، وأنزل المعوذتين. ولم ينتقم ﷺ من الساحر وقال: «أما أنا فقد شفاني الله، وكرهت أن أثير على الناس شرا».",
                "حدود أثر السحر" to "• كان أثرا في البدن كالمرض والتعب، وفي بعض الأمور الدنيوية كما في رواية: «حتى كان يرى أنه يأتي النساء ولا يأتيهن».\n• لم يدخل على عقله ولا على شيء من الوحي والتبليغ، قال القاضي عياض: لم يأت في خبر أنه نقل عنه في ذلك قول بخلاف ما كان أخبر به.\n• وقال المازري: الدليل قد قام على صدق النبي ﷺ فيما يبلغه عن الله وعلى عصمته في التبليغ، وأما ما يتعلق ببعض أمور الدنيا التي لم يبعث لأجلها فهو فيها عرضة لما يعرض للبشر كالأمراض.",
                "شبهة: يوافق قول المشركين ﴿إن تتبعون إلا رجلا مسحورا﴾" to "المشركون أرادوا أنه مجنون مخبول العقل، وأن ما يأتي به من القرآن هذيان سحر، والله رد عليهم ذلك. أما الحديث فيثبت مرضا عارضا في البدن مدة يسيرة ثم شفاه الله، وهذا لا ينافي النبوة. فقد شج وجهه ﷺ يوم أحد وكسرت رباعيته، وسم في خيبر، وكان يمرض ويوعك كما يوعك رجلان، ولم يقدح ذلك في نبوته. والأنبياء بشر يصيبهم ما يصيب البشر من البلاء، بل هم أشد الناس بلاء.",
                "من فوائد الحديث" to "• إثبات حقيقة السحر وتأثيره بإذن الله: ﴿وما هم بضارين به من أحد إلا بإذن الله﴾ [البقرة: 102].\n• أن علاج السحر يكون باستخراجه وإبطاله، وبالرقية الشرعية والمعوذتين، لا بالذهاب إلى السحرة.\n• حلم النبي ﷺ وعفوه، وتقديمه مصلحة الناس على الانتقام لنفسه.\n• تحريم السحر وأنه من كبائر الذنوب.\n• فضل المعوذتين.",
            ),
            sources = listOf(
                "صحيح البخاري (5763، 5765)، صحيح مسلم (2189)",
                "النووي، المنهاج شرح صحيح مسلم (ونقل كلام المازري والقاضي عياض)",
                "ابن حجر، فتح الباري، كتاب الطب، باب السحر",
                "ابن القيم، زاد المعاد، فصل في هديه ﷺ في علاج السحر",
            ),
        ),

        Extra("dhubab", "حديث الذباب", listOf("8363"),
            hadith = "عن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ: «إذا وقع الذباب في شراب أحدكم فليغمسه، ثم لينزعه، فإن في أحد جناحيه داء، وفي الأخرى شفاء». رواه البخاري (3320، 5782).",
            note = "الحديث صحيح في البخاري. والأمر بالغمس للإرشاد لمن أراد أن يشرب، وليس فيه إلزام لأحد بشرب ما تعافه نفسه. وهو أصل عند الفقهاء في أن ما لا دم له سائل إذا مات في الماء لا ينجسه.",
            sections = listOf(
                "تخريج الحديث" to "رواه البخاري في صحيحه (3320) في كتاب بدء الخلق، و(5782) في كتاب الطب، من حديث أبي هريرة. ورواه أبو داود وابن ماجه وأحمد، وجاء من حديث أبي سعيد الخدري عند النسائي وابن ماجه، فهو ثابت من أكثر من وجه.",
                "معنى الحديث" to "إذا سقط الذباب في الشراب فإنه يتقي بالجناح الذي فيه الداء، كما في رواية أبي داود: «وإنه يتقي بجناحه الذي فيه الداء». فأرشد النبي ﷺ إلى غمسه كله ليخرج ما في الجناح الآخر من الشفاء فيقابل الداء، ثم يرمى الذباب.",
                "الحكم الفقهي" to "• استدل به العلماء على أن ما لا نفس له سائلة (لا دم له يسيل) كالذباب والنحل والنمل لا ينجس الماء إذا مات فيه، لأن الغمس قد يقتله، ولو كان ينجس الماء لما أمر بغمسه.\n• الأمر للإرشاد، فمن غمسه ثم عافت نفسه الشراب فله أن يتركه، فلم يأمر ﷺ بالشرب.",
                "شبهة مخالفة الطب" to "1. الحديث خبر من الصادق المصدوق ﷺ الذي لا ينطق عن الهوى، وخبره لا يرد بالظن ولا بالاستبعاد.\n2. الحديث لا يقول إن الذباب نظيف، بل يقرر أن فيه داء، وهذا موافق لما يعرفه الناس. وزاد عليه أن في جناحه الآخر شفاء يقابله، وهذا أمر لا يعرف إلا بالوحي.\n3. علم الطب يتغير ويتجدد، وكم من أمر نفاه الناس ثم ثبت، وقد ذكر بعض الباحثين المعاصرين وجود مواد مضادة للجراثيم في بعض الحشرات. والمسلم لا يعلق إيمانه بالحديث على تجربة، بل يصدقه لصحته.\n4. ليس في الحديث أمر بالشرب، فمن تقذره تركه.",
                "من فوائد الحديث" to "• أن الله جعل في المخلوق الواحد الداء والدواء.\n• عناية الشريعة بحفظ المال وعدم إتلاف الطعام والشراب لأدنى سبب.\n• طهارة ما لا دم له سائل.\n• تصديق خبر النبي ﷺ فيما بلغنا من الغيب.",
            ),
            sources = listOf(
                "صحيح البخاري (3320، 5782)، سنن أبي داود (3844)",
                "ابن حجر، فتح الباري، كتاب الطب، باب إذا وقع الذباب في الإناء",
                "ابن القيم، زاد المعاد، فصل في هديه ﷺ في وقوع الذباب في الإناء",
            ),
        ),

        Extra("naqisat", "«ناقصات عقل ودين»", listOf("10011"),
            hadith = "عن أبي سعيد الخدري رضي الله عنه قال: خرج رسول الله ﷺ في أضحى أو فطر إلى المصلى، فمر على النساء فقال: «يا معشر النساء تصدقن فإني أريتكن أكثر أهل النار» فقلن: وبم يا رسول الله؟ قال: «تكثرن اللعن، وتكفرن العشير، ما رأيت من ناقصات عقل ودين أذهب للب الرجل الحازم من إحداكن» قلن: وما نقصان ديننا وعقلنا يا رسول الله؟ قال: «أليس شهادة المرأة مثل نصف شهادة الرجل» قلن: بلى، قال: «فذلك من نقصان عقلها، أليس إذا حاضت لم تصل ولم تصم» قلن: بلى، قال: «فذلك من نقصان دينها». متفق عليه: البخاري (304) ومسلم (79، 80).",
            note = "النبي ﷺ نفسه فسر النقص: نقص العقل في باب الشهادة (شهادة امرأتين بشهادة رجل)، ونقص الدين بترك الصلاة والصوم في الحيض. وهذا ليس ذنبا تأثم به المرأة ولا ذما لها، بل تؤجر على امتثال أمر الله، وليس معناه أن كل امرأة أقل عقلا ودينا من كل رجل.",
            sections = listOf(
                "تخريج الحديث" to "متفق عليه: البخاري (304) من حديث أبي سعيد، ومسلم (79) من حديث ابن عمر و(80) من حديث أبي سعيد.",
                "سياق الحديث" to "كانت موعظة يوم العيد للنساء، حثهن فيها النبي ﷺ على الصدقة لأنها تقي من النار. وسبب كثرتهن في النار أفعال يمكن تركها: كثرة اللعن، وكفران العشير (جحود إحسان الزوج). فالعتاب على أفعال لا على الخلقة، والعلاج المذكور الصدقة والاستغفار.",
                "معنى نقص العقل" to "فسره النبي ﷺ بأن شهادة المرأتين بشهادة رجل، وعلة ذلك في القرآن: ﴿أن تضل إحداهما فتذكر إحداهما الأخرى﴾ [البقرة: 282]، أي من جهة الضبط والحفظ في باب الشهادات المالية ونحوها، لغلبة العاطفة وانشغالها بشؤون الحمل والولادة والبيت. ولا يعني نقصا في فهمها وذكائها في سائر الأمور، فقد قبلت شهادتها وحدها فيما لا يطلع عليه إلا النساء، وروايتها للحديث مقبولة كالرجل.\nقال ابن باز ما معناه: ليس معنى نقص عقلها أنها مجنونة أو ناقصة العقل في كل شيء، وإنما هو نقص في باب الضبط المتعلق بالشهادة كما بينه النبي ﷺ.",
                "معنى نقص الدين" to "فسره النبي ﷺ بترك الصلاة والصوم وقت الحيض والنفاس. وهذا بأمر الله، فلا إثم عليها فيه، بل تؤجر على امتثالها، وتقضي الصوم دون الصلاة تخفيفا من الله. ولا يلزم من ذلك أن تكون المرأة أقل منزلة عند الله، فالتفاضل بالتقوى: ﴿إن أكرمكم عند الله أتقاكم﴾ [الحجرات: 13]. وكم من امرأة أفضل من آلاف الرجال، كمريم وآسية وخديجة وفاطمة وعائشة.",
                "دفع الشبهة" to "• الحديث وصف لحكم شرعي بينه النبي ﷺ بنفسه، لا إهانة للمرأة.\n• في الحديث نفسه ثناء ضمني: «أذهب للب الرجل الحازم من إحداكن»، أي أن لها تأثيرا قويا حتى على العاقل الحازم.\n• الإسلام كرم المرأة أما وبنتا وزوجة، وجعل الجنة تحت أقدام الأمهات، وأوصى بها النبي ﷺ في حجة الوداع: «استوصوا بالنساء خيرا».",
                "من فوائد الحديث" to "• مشروعية وعظ النساء وتعليمهن، وخروجهن إلى مصلى العيد.\n• فضل الصدقة وأنها تقي من النار.\n• التحذير من كثرة اللعن وجحود إحسان الزوج.\n• جواز مراجعة العالم وسؤاله عما أشكل، فقد سألن النبي ﷺ فأجابهن.",
            ),
            sources = listOf(
                "صحيح البخاري (304)، صحيح مسلم (79، 80)",
                "ابن حجر، فتح الباري، كتاب الحيض",
                "ابن باز، مجموع الفتاوى، فتوى معنى نقصان عقل المرأة ودينها",
                "النووي، المنهاج شرح صحيح مسلم، كتاب الإيمان",
            ),
        ),

        Extra("shams", "سجود الشمس تحت العرش", listOf("65070"),
            hadith = "عن أبي ذر رضي الله عنه قال: قال النبي ﷺ لأبي ذر حين غربت الشمس: «أتدري أين تذهب؟» قلت: الله ورسوله أعلم، قال: «فإنها تذهب حتى تسجد تحت العرش، فتستأذن فيؤذن لها، ويوشك أن تسجد فلا يقبل منها، وتستأذن فلا يؤذن لها، يقال لها: ارجعي من حيث جئت، فتطلع من مغربها، فذلك قوله تعالى: ﴿والشمس تجري لمستقر لها ذلك تقدير العزيز العليم﴾». متفق عليه: البخاري (3199) ومسلم (159).",
            note = "سجود الشمس عبادة وخضوع لله لا نعلم كيفيتها، كتسبيح المخلوقات الذي لا نفقهه. ولا يلزم منه أن تتوقف عن جريانها، والعرش فوق المخلوقات كلها فهي تحته في كل وقت، فلا تعارض بين الحديث وما يشاهد من دوران الأفلاك.",
            sections = listOf(
                "تخريج الحديث" to "متفق عليه من حديث أبي ذر: البخاري (3199، 4802، 7424) ومسلم (159).",
                "سجود المخلوقات في القرآن" to "• ﴿ألم تر أن الله يسجد له من في السماوات ومن في الأرض والشمس والقمر والنجوم والجبال والشجر والدواب﴾ [الحج: 18].\n• ﴿وإن من شيء إلا يسبح بحمده ولكن لا تفقهون تسبيحهم﴾ [الإسراء: 44].\nفسجود كل مخلوق بحسبه، والشمس تسجد سجودا يليق بها لا نعلم كيفيته، كما أن تسبيح الحجر والشجر حقيقي ولا نفقهه.",
                "شبهة مخالفة علم الفلك" to "قالوا: الشمس لا تغيب عن الأرض، فهي دائما طالعة على قوم، فكيف تذهب فتسجد؟\nوالجواب:\n1. العرش سقف المخلوقات كلها، محيط بها من فوق، فالشمس تحت العرش في كل وقت وفي أي موضع كانت، فلا يلزم أن تنتقل إلى مكان آخر لتكون تحته.\n2. السجود والاستئذان أمر غيبي لا يدرك بالمشاهدة ولا بالمراصد، فلا يصح نفيه بها. قال الخطابي ما معناه: لا ينكر أن يكون لها استقرار تحت العرش من حيث لا ندركه ولا نشاهده.\n3. سجودها لا يقتضي سكونها عن الجري، فهي تسجد وهي جارية، كما يسبح الطير وهو يطير.\n4. ذكر ابن عثيمين ما معناه: أن الحديث خبر من الصادق، نؤمن به ونقول: الله أعلم بكيفيته، ولا تعارض بين الخبر الصحيح والواقع الصحيح.",
                "طلوع الشمس من مغربها" to "في آخر الحديث أن الشمس يوما يقال لها: ارجعي من حيث جئت، فتطلع من مغربها، وذلك من علامات الساعة الكبرى. وعنده يغلق باب التوبة: ﴿يوم يأتي بعض آيات ربك لا ينفع نفسا إيمانها لم تكن آمنت من قبل﴾ [الأنعام: 158]، وقال ﷺ: «من تاب قبل أن تطلع الشمس من مغربها تاب الله عليه» (مسلم).",
                "من فوائد الحديث" to "• أن جميع المخلوقات خاضعة لله، مسخرة بأمره.\n• إثبات العرش وأنه فوق المخلوقات.\n• تفسير النبي ﷺ للقرآن: ﴿والشمس تجري لمستقر لها﴾.\n• المبادرة بالتوبة قبل طلوع الشمس من مغربها.\n• حسن تعليم النبي ﷺ بالسؤال: «أتدري أين تذهب؟».",
            ),
            sources = listOf(
                "صحيح البخاري (3199)، صحيح مسلم (159)",
                "ابن حجر، فتح الباري، كتاب بدء الخلق، باب صفة الشمس والقمر (ونقل كلام الخطابي)",
                "ابن عثيمين، مجموع فتاوى ورسائل العثيمين، مسائل في العقيدة",
            ),
        ),

        Extra("musa", "موسى عليه السلام وملك الموت", listOf("66299"),
            hadith = "عن أبي هريرة رضي الله عنه قال: «أرسل ملك الموت إلى موسى عليهما السلام، فلما جاءه صكه، فرجع إلى ربه فقال: أرسلتني إلى عبد لا يريد الموت، فرد الله عليه عينه وقال: ارجع فقل له يضع يده على متن ثور، فله بكل ما غطت به يده بكل شعرة سنة، قال: أي رب، ثم ماذا؟ قال: ثم الموت، قال: فالآن، فسأل الله أن يدنيه من الأرض المقدسة رمية بحجر». متفق عليه: البخاري (1339) ومسلم (2372).",
            note = "جاء ملك الموت موسى عليه السلام في صورة رجل لا يعرفه، يريد قبض روحه دون تخيير، فدافع موسى عن نفسه كما يدفع المرء من اقتحم عليه. فلما رجع إليه وخيره وعرف أنه رسول ربه، اختار الموت ولقاء الله في الحال. ولم يقع شيء من ذلك على حقيقة الملك، وإنما على الصورة التي تمثل بها.",
            sections = listOf(
                "تخريج الحديث" to "متفق عليه من حديث أبي هريرة: البخاري (1339، 3407) ومسلم (2372). وقد احتج به الأئمة وشرحوه، وأجابوا عما يستشكل منه، ومنهم ابن خزيمة وابن حبان والخطابي والنووي وابن حجر.",
                "أجوبة العلماء" to "1. أن ملك الموت جاءه في صورة آدمي لم يعرفه، فدخل عليه بلا إذن يريد نفسه، فدفعه موسى عن نفسه، والشريعة تبيح دفع الصائل، وقد قال النبي ﷺ: «لو أن امرأ اطلع عليك بغير إذن فخذفته بحصاة ففقأت عينه لم يكن عليك جناح» (متفق عليه). وهذا جواب ابن خزيمة وغيره.\n2. أن الأنبياء لا تقبض أرواحهم حتى يخيروا، كما قالت عائشة: سمعت النبي ﷺ يقول: «ما من نبي يمرض إلا خير بين الدنيا والآخرة» (متفق عليه). فلما جاءه الملك أولا بلا تخيير دفعه، فلما رجع إليه مخيرا اختار الموت فورا بقوله «فالآن».\n3. أن العين التي فقئت عين الصورة التي تمثل بها الملك، لا حقيقة الملك، والملائكة يتشكلون بإذن الله، ولذلك رد الله عليه عينه.",
                "دفع الشبهة" to "• ليس في الحديث كراهية موسى للقاء الله، بل لما خير اختار الموت مباشرة دون أن يطلب السنين الكثيرة المعروضة عليه.\n• ليس فيه اعتداء على الملائكة، لأنه لم يعرفه، ودفع من هجم على بيته ونفسه.\n• قول الملك «لا يريد الموت» إخبار عما رآه من دفعه، والله أعلم بحال عبده، ولذلك أكرمه بالتخيير.",
                "من فوائد الحديث" to "• كرامة الأنبياء على الله، وأنهم يخيرون عند الموت.\n• أن الملائكة يتمثلون في صورة البشر بإذن الله.\n• فضل الأرض المقدسة، واستحباب الدفن في الأماكن الفاضلة وقرب الصالحين.\n• أن الآجال مكتوبة لا تزيد ولا تنقص، وأن الموت آت مهما طال العمر: «ثم ماذا؟ قال: ثم الموت».\n• قال ﷺ في آخر الحديث: «فلو كنت ثم لأريتكم قبره إلى جانب الطريق عند الكثيب الأحمر».",
            ),
            sources = listOf(
                "صحيح البخاري (1339، 3407)، صحيح مسلم (2372)",
                "النووي، المنهاج شرح صحيح مسلم، كتاب الفضائل",
                "ابن حجر، فتح الباري، كتاب الجنائز (ونقل أجوبة ابن خزيمة والخطابي)",
            ),
        ),

        Extra("uqatil", "«أمرت أن أقاتل الناس»", listOf("4211"),
            hadith = "عن ابن عمر رضي الله عنهما أن رسول الله ﷺ قال: «أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله وأن محمدا رسول الله، ويقيموا الصلاة، ويؤتوا الزكاة، فإذا فعلوا ذلك عصموا مني دماءهم وأموالهم إلا بحق الإسلام، وحسابهم على الله». متفق عليه: البخاري (25) ومسلم (22).",
            note = "ليس معناه إكراه الناس على الدخول في الإسلام، فالله يقول: ﴿لا إكراه في الدين﴾. و«أقاتل» غير «أقتل»، والمقاتلة تكون مع من يحارب. وأهل الكتاب ومن في حكمهم تقبل منهم الجزية ويقرون على دينهم، والمعاهد والذمي والمستأمن دماؤهم معصومة. وإعلان القتال من شأن ولي الأمر لا آحاد الناس.",
            sections = listOf(
                "تخريج الحديث" to "متفق عليه من حديث ابن عمر: البخاري (25) ومسلم (22)، وجاء نحوه عن أبي هريرة وأنس وغيرهما. وهو الحديث الثامن في الأربعين النووية.",
                "«أقاتل» لا «أقتل»" to "المقاتلة مفاعلة تكون بين طرفين، فهي لمن يقاوم ويحارب، لا لمن سالم وكف. قال ابن دقيق العيد ما معناه: لا يلزم من إباحة المقاتلة إباحة القتل، فالمقاتلة مشروطة بالمقاومة والممانعة.",
                "من المقصود بـ«الناس»؟" to "للعلماء فيه أقوال، منها:\n• أنه عام أريد به خاص، والمراد المشركون المحاربون، بدليل قوله تعالى: ﴿قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر... حتى يعطوا الجزية عن يد وهم صاغرون﴾ [التوبة: 29]، فأهل الكتاب يقرون بالجزية، وأخذها النبي ﷺ من مجوس هجر.\n• أن الغاية المذكورة (حتى يشهدوا) غاية لمن قوتل، وقد ينتهي القتال قبلها بالجزية أو العهد أو الصلح كما في صلح الحديبية.\nفالحديث لا ينسخ آيات العهد والسلم: ﴿وإن جنحوا للسلم فاجنح لها﴾ [الأنفال: 61].",
                "حرمة دماء غير المسلمين المسالمين" to "• قال ﷺ: «من قتل معاهدا لم يرح رائحة الجنة» (البخاري 3166).\n• ﴿لا ينهاكم الله عن الذين لم يقاتلوكم في الدين ولم يخرجوكم من دياركم أن تبروهم وتقسطوا إليهم﴾ [الممتحنة: 8].\n• الجهاد وإعلان الحرب من صلاحيات ولي الأمر، وليس لآحاد الناس أن يفتاتوا عليه، كما قرر العلماء. ومن استدل بهذا الحديث على قتل المسالمين أو المعاهدين فقد ضل عن معناه.",
                "من فوائد الحديث" to "• أن الشهادتين تعصمان الدم والمال، ومن قالهما وجب الكف عنه، كما في قصة أسامة: «أقتلته بعدما قال لا إله إلا الله؟».\n• عظم شأن الصلاة والزكاة، ولذلك قاتل أبو بكر رضي الله عنه مانعي الزكاة واحتج بهذا الحديث.\n• أننا نحكم بالظاهر، و«حسابهم على الله» في السرائر.\n• «إلا بحق الإسلام»: أي إلا أن يفعل ما يوجب حدا أو قصاصا.",
            ),
            sources = listOf(
                "صحيح البخاري (25)، صحيح مسلم (22)",
                "ابن رجب، جامع العلوم والحكم، شرح الحديث الثامن",
                "ابن عثيمين، شرح الأربعين النووية، الحديث الثامن",
                "ابن حجر، فتح الباري، كتاب الإيمان",
            ),
        ),

        Extra("shum", "«الشؤم في ثلاث»", emptyList(),
            hadith = "عن ابن عمر رضي الله عنهما قال: سمعت النبي ﷺ يقول: «إنما الشؤم في ثلاثة: في الفرس، والمرأة، والدار». متفق عليه: البخاري (5093) ومسلم (2225). وفي رواية: «إن كان الشؤم في شيء ففي الدار والمرأة والفرس» البخاري (5094) ومسلم (2225).",
            note = "ليس الحديث إقرارا للتطير والتشاؤم، فالنبي ﷺ قال: «لا عدوى ولا طيرة». والمعنى عند كثير من العلماء: أن بعض هذه الثلاث قد لا توافق صاحبها فيجد منها ضررا أو كراهة بقدر الله لا بذاتها، فيشرع له مفارقتها. وليس فيه ذم للنساء، بل هو في امرأة بعينها لا يوافق خلقها زوجها، كما أن من الأزواج من يكون شقاء على زوجته.",
            sections = listOf(
                "تخريج الحديث" to "متفق عليه من حديث ابن عمر: البخاري (5093، 5094، 2858) ومسلم (2225)، ومن حديث سهل بن سعد: البخاري (5095) ومسلم (2226) بلفظ: «إن كان ففي الفرس والمرأة والمسكن».",
                "الجمع بينه وبين «لا طيرة»" to "1. رواية «إن كان الشؤم في شيء» تدل على أن المعنى: لو كان للشؤم حقيقة لكان في هذه الثلاث، لكثرة ملازمة الإنسان لها، فهو نفي لحقيقة الشؤم لا إثبات له. وهو قول جماعة من العلماء.\n2. أن الشؤم هنا ليس تطيرا، بل ما يجده الإنسان من الضرر والنكد من هذه الأشياء بقدر الله. وفسره بعض السلف: شؤم الدار ضيقها وسوء جيرانها، وشؤم المرأة سوء خلقها وعدم طاعتها، وشؤم الفرس ألا يغزى عليه أو أن يكون جموحا. وقرره ابن القيم في «مفتاح دار السعادة»: أن الله قد يخلق بعض الأعيان مشؤومة على من قاربها بقدره، وذلك غير الطيرة المنهي عنها التي هي ظن الشر بالمسموع والمرئي.\n3. أنكرت عائشة رضي الله عنها هذا اللفظ وقالت: إنما كان أهل الجاهلية يقولون ذلك (رواه أحمد). والجمهور قبلوا الحديث لثبوته من طرق متعددة في الصحيحين، وحملوه على المعاني السابقة.",
                "الفرق بين الشؤم المذكور والطيرة المحرمة" to "• الطيرة المحرمة: أن يتشاءم بشيء يراه أو يسمعه، فيرده عن حاجته، كالتشاؤم بالطيور والأرقام والأيام، وهي شرك أصغر: «الطيرة شرك».\n• المذكور في الحديث: كراهة دائمة يجدها الإنسان في مسكن أو زوجة أو دابة لا تلائمه، فأرشده الشرع إلى مفارقتها ليرتاح، كما قال ﷺ في دار قل فيها عددهم ومالهم: «ذروها ذميمة» (أبو داود).",
                "دفع الشبهة عن المرأة" to "• ليس المقصود جنس النساء، بل امرأة بعينها لا يوافق حالها زوجها.\n• ذكرت المرأة مع الدار والفرس لأنها مما يلازمه الرجل طويلا، والرجل كذلك قد يكون شؤما على زوجته بسوء خلقه، والشريعة جعلت لها الخلع.\n• الإسلام أوصى بالمرأة وجعل خير الناس خيرهم لأهله، وقال ﷺ: «الدنيا متاع، وخير متاع الدنيا المرأة الصالحة» (مسلم).",
                "من فوائد الحديث" to "• نفي التطير وأن الأمور كلها بقدر الله.\n• إباحة مفارقة ما يجد الإنسان فيه ضررا أو كراهة دائمة من مسكن ونحوه.\n• حسن اختيار الزوجة والمسكن والمركب، وفي الحديث: «أربع من السعادة: المرأة الصالحة، والمسكن الواسع، والجار الصالح، والمركب الهنيء» (ابن حبان).",
