    private val byId: Map<String, Extra> = list.flatMap { e -> e.ids.map { it to e } }.toMap()
    fun of(id: String): Extra? = byId[id]
    fun byKey(key: String): Extra? = list.firstOrNull { it.key == key }

    /** Plain text of the extra explanation, for copy/share. */
    fun text(e: Extra): String = buildString {
        append("تنبيه: ").append(e.note).append("\n\n")
        e.sections.forEach { (h, b) -> append(h).append('\n').append(b).append("\n\n") }
        append("المصادر:\n"); e.sources.forEach { append("• ").append(it).append('\n') }
    }

    /** The first words of the hadith, without marks or punctuation, as a search phrase. */
    fun phrase(title: String, text: String): String {
        val src = title.ifBlank { text }
        val clean = src.replace(Regex("[\\u064B-\\u065F\\u0670\\u06D6-\\u06ED]"), "")
            .replace(Regex("[^\\p{L}\\p{N}\\s]"), " ").trim()
        return clean.split(Regex("\\s+")).filter { it.isNotBlank() }.take(9).joinToString(" ")
    }

    class Site(val label: String, val url: (String) -> String)
    val sites = listOf(
        Site("الدرر السنية") { q -> "https://dorar.net/hadith/search?q=" + Uri.encode(q) },
        Site("إسلام ويب") { q -> "https://www.google.com/search?q=" + Uri.encode("site:islamweb.net $q") },
        Site("الإسلام سؤال وجواب") { q -> "https://www.google.com/search?q=" + Uri.encode("site:islamqa.info/ar $q") },
    )

    fun open(c: Context, url: String) {
        runCatching { c.startActivity(Intent(Intent.ACTION_VIEW, Uri.parse(url)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)) }
    }
}
